sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 offset;
uniform float cell;
uniform float stretch;
uniform float angle;
uniform float colors;
layout(color) uniform half4 color1;
layout(color) uniform half4 color2;
layout(color) uniform half4 color3;
uniform float opacity;
uniform float blend;
uniform float gap;
uniform float feather;
float hash11(float p) {
    p = fract(p * 0.1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}
float hash21(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash21(i), hash21(i + float2(1, 0)), f.x), mix(hash21(i + float2(0, 1)), hash21(i + float2(1, 1)), f.x), f.y);
}
float fbm(float2 p) {
    float s = 0.0;
    float a = 0.5;
    for (int i = 0; i < 5; i++) {
        s += a * vnoise(p);
        p = p * 2.03 + float2(17.1, 9.7);
        a *= 0.5;
    }
    return s / 0.96875;
}
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float r = radians(angle);
    float2 p = coord - 0.5 * size - offset;
    p = float2(cos(r) * p.x + sin(r) * p.y, -sin(r) * p.x + cos(r) * p.y);
    p = float2(p.x, p.y / max(stretch, 0.05)) / max(cell, 2.0);
    float2 rr = float2(1.0, 1.7320508);
    float2 a = mod(p, rr) - 0.5 * rr;
    float2 b = mod(p - 0.5 * rr, rr) - 0.5 * rr;
    float2 gv = dot(a, a) < dot(b, b) ? a : b;
    float2 id = p - gv;
    float2 q = abs(gv);
    float dist = max(dot(q, float2(0.5, 0.8660254)), q.x);
    float inner = 0.5 - 0.5 * gap;
    float cover = 1.0 - smoothstep(inner - 0.5 * feather, inner, dist);
    float pick = floor(hash21(float2(floor(id.x * 2.0 + 0.5), floor(id.y / 0.8660254 + 0.5))) * (colors + 1.0));
    half4 s = pick < 0.5 ? color1 : (pick < 1.5 ? color2 : color3);
    float3 base = float3(unpremul(c).rgb);
    float3 rgb = mix(base, clamp(blendWith(blend, base, float3(s.rgb)), 0.0, 1.0), clamp(opacity, 0.0, 1.0) * cover * float(s.a));
    return half4(half3(rgb) * c.a, c.a);
}
